contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Acts as the access-control contract: grants every checkAccess request.
    fallback(bytes calldata) external returns (bytes memory) {
        return abi.encode(true);
    }

    receive() external payable {}

    function run(uint256 kink) public {
        c.initialize(address(this));

        bool reverted;
        try c.setSlopes(address(0x1234), IVaultAdapter.SlopeData({kink: kink, slope0: 1, slope1: 2})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool shouldRevert = (kink == 0 || kink >= 1e27);
        assert(reverted == shouldRevert);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    fallback(bytes calldata data) external returns (bytes memory) {
        // IAccessControl.checkAccess(bytes4,address,address) => 100 bytes: grant access.
        // IVault.currentUtilizationIndex(address) (36 bytes) and
        // IVault.utilization(address) (68 bytes): return uint256(0).
        if (data.length >= 100) {
            return abi.encode(true);
        }
        return abi.encode(uint256(0));
    }

    receive() external payable {}

    function run(address asset, uint256 kink) public {
        require(kink > 0 && kink < 1e27);

        c.initialize(address(this));

        IVaultAdapter.SlopeData memory slopes =
            IVaultAdapter.SlopeData({kink: kink, slope0: 0, slope1: 0});
        c.setSlopes(asset, slopes);

        c.setLimits(1e30, 1e27, 1e18);

        // This test contract acts as the vault, reporting zero utilization.
        uint256 result = c.rate(address(this), asset);

        // With slope0 == slope1 == 0 the interest rate must be exactly zero,
        // no matter the kink or the reported utilization.
        assert(result == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    fallback(bytes calldata data) external returns (bytes memory) {
        // IAccessControl.checkAccess(bytes4,address,address) has 100 bytes of calldata.
        // IVault.currentUtilizationIndex(address) (36 bytes) and IVault.utilization(address)
        // (68 bytes): return a huge index so utilization = index/elapsed >= 1.
        if (data.length >= 100) {
            return abi.encode(true);
        }
        return abi.encode(uint256(type(uint256).max));
    }

    receive() external payable {}

    function run(address asset) public {
        // Fresh C has initializers disabled, so accessControl stays address(0)
        // and every access-checked call must revert.
        bool slopesReverted;
        IVaultAdapter.SlopeData memory slopes =
            IVaultAdapter.SlopeData({kink: 5e26, slope0: 1e27, slope1: 2e27});
        try c.setSlopes(asset, slopes) {
            slopesReverted = false;
        } catch {
            slopesReverted = true;
        }

        bool limitsReverted;
        try c.setLimits(1e30, 1e27, 1e18) {
            limitsReverted = false;
        } catch {
            limitsReverted = true;
        }

        // rate() itself is unguarded; with unset (all-zero) slope data and
        // nonzero utilization (this contract as the vault reports a huge index)
        // the interest rate must be exactly 0.
        uint256 result = c.rate(address(this), asset);

        assert(slopesReverted && limitsReverted && result == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    fallback(bytes calldata data) external returns (bytes memory) {
        // IAccessControl.checkAccess has 100 bytes of calldata; IVault getters are shorter.
        if (data.length >= 100) {
            return abi.encode(true);
        }
        // Report a huge utilization/index so rate() exercises the above-kink branch.
        return abi.encode(uint256(type(uint256).max));
    }

    receive() external payable {}

    function run(uint256 maxMultiplier, uint256 minMultiplier, uint256 rate) public {
        // Fresh C has initializers disabled (constructor called _disableInitializers),
        // so the access control is unset and access-guarded setters must revert.
        bool limitsReverted;
        try c.setLimits(maxMultiplier, minMultiplier, rate) {
            limitsReverted = false;
        } catch {
            limitsReverted = true;
        }

        // rate() is unguarded; with default zero slopes the returned rate must be 0.
        uint256 result = c.rate(address(this), address(0x1));

        assert(limitsReverted && result == 0);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    fallback(bytes calldata) external returns (bytes memory) {
        // IVault views report a large nonzero utilization; checkAccess calls go to
        // address(0) and never reach here, so this is only reached for utilization.
        return abi.encode(uint256(type(uint256).max));
    }

    receive() external payable {}

    function run(address vault, address asset) public {
        require(uint160(vault) != 0);

        bool reverted;
        try c.setLimits(1, 1, 1) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 result = c.rate(vault, asset);

        assert(reverted && result == 0);
    }
}

