contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 kink, uint256 slope0, uint256 slope1) public {
        // grant access to the test contract by making it the access control
        c.initialize(address(this));

        IVaultAdapter.SlopeData memory slopes;
        slopes.kink = kink;
        slopes.slope0 = slope0;
        slopes.slope1 = slope1;

        bool reverted;
        try c.setSlopes(address(0x1), slopes) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool kinkInvalid = (kink == 0 || kink >= 1e27);
        assert(reverted == kinkInvalid);
    }

    fallback(bytes calldata input) external payable returns (bytes memory) {
        // emulate IAccessControl.checkAccess -> true for the access check from c
        if (input.length >= 4 && bytes4(input) == IAccessControl.checkAccess.selector) {
            return abi.encode(true);
        }
        return "";
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    uint256 vaultIndex;
    uint256 vaultUtilization;

    constructor(C _c) { c = _c; }

    function run(uint256 idx, uint256 util) public {
        require(util > 0, "need positive utilization");
        vaultIndex = idx;
        vaultUtilization = util;
        // address(this) acts as the IVault backing c; address param of rate is irrelevant
        uint256 r = c.rate(address(this), address(0x1));
        assert(r == 0);
    }

    fallback(bytes calldata input) external payable returns (bytes memory) {
        if (input.length >= 4) {
            bytes4 sel = bytes4(input);
            // currentUtilizationIndex(address)
            if (sel == IVault.currentUtilizationIndex.selector) {
                return abi.encode(vaultIndex);
            }
            // utilization(address)
            if (sel == IVault.utilization.selector) {
                return abi.encode(vaultUtilization);
            }
        }
        return "";
    }
    receive() external payable {}
}

