contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address accessControl) public {
        // First initialization on a fresh C must succeed for any address.
        bool firstReverted;
        c.initialize(accessControl);
        // Setup done; now attempt a second initialization.
        bool secondReverted;
        try c.initialize(accessControl) {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }
        assert(secondReverted);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 kink, address asset) public {
        require(kink < 1e27 || kink >= 1e27); // always true; kink is unconstrained
        // Make this contract the access controller; fallback grants access.
        c.initialize(address(this));

        bool reverted;
        IVaultAdapter.SlopeData memory slopes;
        slopes.kink = kink;
        slopes.slope0 = 1;
        slopes.slope1 = 1;
        try c.setSlopes(asset, slopes) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted == (kink == 0 || kink >= 1e27));
    }

    fallback(bytes calldata input) external returns (bytes memory) {
        if (bytes4(input) == IAccessControl.checkAccess.selector) {
            return abi.encode(true);
        }
        return "";
    }
}
